package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamRightsBank2 {
  private const val T = "මානව හිමිකම්, මූලික අයිතිවාසිකම් හා පුරවැසි යුතුකම්"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("පුරාණ ඉතිහාසයේ ප්‍රථම මානව හිමිකම් ප්‍රකාශනයක් ලෙස සැලකෙන ක්‍රි.පූ. 539 සයිරස් සිලින්ඩරයෙන් ප්‍රකාශ වූයේ කුමක්ද?", "වහලුන් නිදහස් කිරීම හා ආගමික නිදහස පිළිගැනීම", "බදු අනුපාත දෙගුණ කිරීම", "සියලු විදේශිකයන් පිටුවහල් කිරීම", "රාජාණ්ඩුව අහෝසි කිරීම", "පර්සියානු රජු සයිරස් විසින් වහල්භාවය තහනම් කර ආගමික හා සංස්කෘතික නිදහස ප්‍රකාශ කළේය."),
    q("1776 ඇමරිකානු නිදහස් ප්‍රකාශනයේ සඳහන් වූ අහිමි කළ නොහැකි මූලික අයිතිවාසිකම් තුන කවරේද?", "ජීවිතය, නිදහස සහ සතුට සොයා යාම", "ධනය, බලය සහ යුද්ධය", "බදු, වෙළඳාම සහ භූමිය", "පන්තිය, කුලය සහ වරප්‍රසාද", "තෝමස් ජෙෆර්සන් රචනා කළ 1776 ප්‍රකාශනය සෑම මිනිසෙකුටම සමානව හිමි මෙම අයිතිවාසිකම් අවධාරණය කළේය."),
    q("1689 ඉංග්‍රීසි අයිතිවාසිකම් පනත (English Bill of Rights) මඟින් ප්‍රධාන වශයෙන් සීමා කරන ලද්දේ කාගේ බලතලද?", "රජුගේ හා විධායකයේ අත්තනෝමතික බලතල", "පාර්ලිමේන්තුවේ කථානායකගේ බලය", "ග්‍රාමීය අධිකරණවල බලය", "වෙළඳ සංගම්වල බලය", "පාර්ලිමේන්තුවේ අනුමැතියකින් තොරව බදු පැනවීම හා නීති අත්හිටුවීමේ රජුගේ බලය ඉන් සීමා විය."),
    q("1978 ශ්‍රී ලංකා ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 13(4) වගන්තිය මඟින් තහවුරු කරන මූලික අයිතිවාසිකම කුමක්ද?", "නිසි අධිකරණයක නියෝගයකින් මිස කිසිවෙකුට මරණ දඬුවම හෝ සිරදඬුවම නියම නොකිරීම", "සෑම දරුවෙකුටම උසස් අධ්‍යාපනය ලබාදීම", "රජයේ ඉඩම් නොමිලේ බෙදාදීම", "විදේශ ගමන් බලපත්‍ර නොමිලේ දීම", "දඬුවම් නියම කිරීමේ බලය පොලිසියට හෝ පරිපාලන නිලධාරීන්ට නොව නිසි අධිකරණයකට පමණක් හිමිවේ."),
    q("1978 ව්‍යවස්ථාවේ 16 වන වගන්තිය අනුව ව්‍යවස්ථාව සම්මත වීමට පෙර පැවති සියලු ලිඛිත හා අලිඛිත නීති සම්බන්ධයෙන් පවතින තත්ත්වය කුමක්ද?", "මූලික අයිතිවාසිකම්වලට පටහැනි වුවද ඒවා තවදුරටත් වලංගු වේ", "වහාම ස්වයංක්‍රීයව අහෝසි වේ", "පළාත් සභාවලින් අනුමත කළ යුතුය", "විදේශිකයන්ට පමණක් බලපායි", "16(1) වගන්තිය අනුව 1978ට පෙර පැවති නීති මූලික අයිතිවාසිකම් පරිච්ඡේදය හේතුවෙන් අවලංගු නොවේ."),
    q("අභියාචනාධිකරණයේ විභාග වන රීට් පෙත්සමකදී මූලික අයිතිවාසිකම් උල්ලංඝනය වූ බවක් පෙනී ගියහොත් 126(3) වගන්තිය අනුව කළ යුත්තේ කුමක්ද?", "එම කරුණ වහාම ශ්‍රේෂ්ඨාධිකරණය වෙත යොමු කිරීම", "පෙත්සම වහාම නිෂ්ප්‍රභ කිරීම", "මහේස්ත්‍රාත් අධිකරණයට ආපසු යැවීම", "පාර්ලිමේන්තු කථානායකට භාර දීම", "රීට් පෙත්සමක මූලික අයිතිවාසිකම් ගැටලුවක් මතු වුවහොත් එය තීරණය කිරීම සඳහා ශ්‍රේෂ්ඨාධිකරණයට යොමු කෙරේ."),
    q("ශ්‍රී ලංකාවේ හදිසි නීති රෙගුලාසි (Public Security Ordinance) ක්‍රියාත්මක වන කාලයේදී පවා කිසිසේත් අත්හිටුවිය නොහැකි අයිතීන් මොනවාද?", "සිතීමේ නිදහස (10) හා වධහිංසාවෙන් නිදහස් වීම (11)", "පෙළපාලි යාමේ හා රැස්වීමේ නිදහස", "තොරතුරු දැනගැනීමේ අයිතිය", "සංචරණ නිදහස", "15(7) වගන්තිය අනුව හදිසි අවස්ථාවල 12, 13(1)-(2), 14 සීමා කළ හැකි වුවද 10 හා 11 වගන්ති කිසිදා සීමා නොවේ."),
    q("ජාත්‍යන්තර වධහිංසා විරෝධී සම්මුතිය (CAT) ක්‍රියාත්මක කිරීම සඳහා ශ්‍රී ලංකාව සම්මත කළ පනත කුමක්ද?", "1994 අංක 22 දරන වධහිංසාවලට එරෙහි සම්මුති පනත", "2003 අංක 09 පාරිභෝගික පනත", "1988 අංක 72 සමථ මණ්ඩල පනත", "2016 අංක 12 තොරතුරු පනත", "වධහිංසාව දඬුවම් ලැබිය හැකි බරපතළ අපරාධයක් බවට 1994 අංක 22 පනතින් නීතිගත කර ඇත."),
    q("ආබාධ සහිත පුද්ගලයන්ගේ අයිතිවාසිකම් ආරක්ෂා කිරීම සඳහා ශ්‍රී ලංකාව 1996 දී පැනවූ නීතිය කුමක්ද?", "ආබාධ සහිත තැනැත්තන්ගේ අයිතිවාසිකම් ආරක්ෂා කිරීමේ පනත", "පළාත් පාලන බදු පනත", "මැතිවරණ වියදම් පනත", "විශ්වවිද්‍යාල පනත", "1996 අංක 28 දරන පනත මඟින් රැකියා, අධ්‍යාපන හා පොදු ස්ථාන ප්‍රවේශ අයිතීන් තහවුරු කෙරිණි."),
    q("1978 ව්‍යවස්ථාවේ 19 වන වගන්තිය අනුව ශ්‍රී ලංකාවේ 'ජාතික භාෂාවන්' ලෙස හඳුන්වා ඇත්තේ මොනවාද?", "සිංහල සහ දෙමළ", "සිංහල, දෙමළ සහ ඉංග්‍රීසි", "සිංහල පමණක්", "පාලි සහ සංස්කෘත", "ව්‍යවස්ථාවේ 19 වන වගන්තිය සිංහල හා දෙමළ යන භාෂා දෙකම ශ්‍රී ලංකාවේ ජාතික භාෂා ලෙස පිළිගනී."),
    q("ශ්‍රී ලංකාවේ පාර්ලිමේන්තු පනත් හා අනුනීති නිකුත් කිරීමේදී 23 වන වගන්තිය අනුව අනුගමනය කළ යුතු භාෂා නීතිය කුමක්ද?", "සිංහල සහ දෙමළ භාෂා දෙකෙන්ම පළ කර ඉංග්‍රීසි පරිවර්තනයද එක් කිරීම", "ඉංග්‍රීසි භාෂාවෙන් පමණක් පළ කිරීම", "සිංහල භාෂාවෙන් පමණක් පළ කිරීම", "පළාත් සභාවට අවශ්‍ය භාෂාවකින් පළ කිරීම", "රටේ සියලු පුරවැසියන්ට නීතිය කියවා තේරුම් ගැනීමට රාජ්‍ය භාෂා දෙකෙන්ම නීති සම්පාදනය කෙරේ."),
    q("රටේ පාසල් අධ්‍යාපනය හා විශ්වවිද්‍යාල ප්‍රවේශ විභාගවලදී 21 වන වගන්තියෙන් දරුවෙකුට හිමිවන භාෂා අයිතිය කුමක්ද?", "සිංහල හෝ දෙමළ යන ජාතික භාෂාවකින් අධ්‍යාපනය ලැබීමේ අයිතිය", "විදේශීය භාෂාවකින් පමණක් ඉගෙනීමට බල කිරීම", "මව් භාෂාව ඉගෙනීම තහනම් කිරීම", "ගුරුවරයාගේ කැමැත්ත මත භාෂාව මාරු කිරීම", "සෑම ශිෂ්‍යයෙකුටම තම ජාතික භාෂා දෙකෙන් එකකින් අධ්‍යාපනය ලැබීමට ව්‍යවස්ථාපිත අයිතියක් ඇත."),
    q("රාජ්‍ය ආයතනවල රාජ්‍ය භාෂා ප්‍රතිපත්තිය නිසි පරිදි ක්‍රියාත්මක වන්නේදැයි අධීක්ෂණය කරන ආයතනය කුමක්ද?", "රාජ්‍ය භාෂා කොමිෂන් සභාව", "විශ්වවිද්‍යාල ප්‍රතිපාදන කොමිසම", "සුරාබදු කොමිසම", "රේගු දෙපාර්තමේන්තුව", "1991 අංක 18 පනතින් පිහිටුවූ රාජ්‍ය භාෂා කොමිෂන් සභාව භාෂා අයිතිවාසිකම් පැමිණිලි විමර්ශනය කරයි."),
    q("එක්සත් ජාතීන්ගේ ළමා අයිතිවාසිකම් ප්‍රඥප්තියේ (UNCRC) 3 වන වගන්තියේ දැක්වෙන ප්‍රමුඛතම මූලධර්මය කුමක්ද?", "දරුවා සම්බන්ධ සෑම තීරණයකදීම 'දරුවාගේ උපරිම යහපත' ප්‍රමුඛ වීම", "දෙමව්පියන්ගේ ආර්ථික ලාභය ප්‍රමුඛ වීම", "පාසල් පරිපාලනයේ පහසුව ප්‍රමුඛ වීම", "පළාත් සභා ආදායම ප්‍රමුඛ වීම", "අධිකරණ, සුබසාධන හා පවුල් තීරණවලදී දරුවාගේ උපරිම යහපත (Best Interests of the Child) ප්‍රධාන වේ."),
    q("UNCRC 7 වන වගන්තියට අනුව දරුවෙකු උපත ලද විගසම ඔහුට හිමිවිය යුතු පළමු නීතිමය අයිතිවාසිකම කුමක්ද?", "උපත ලියාපදිංචි කිරීම, නමක් සහ ජාතිකත්වයක් ලැබීම", "පළමු පන්තියේ විභාගයට පෙනී සිටීම", "රියදුරු බලපත්‍රයක් ලබාගැනීම", "බැංකු ණය පහසුකම් ලබාගැනීම", "නීතිමය අනන්‍යතාවක් නොමැති වීමෙන් දරුවෙකු රාජ්‍ය රැකවරණයෙන් ගිලිහෙන බැවින් උප්පැන්න ලියාපදිංචිය අත්‍යවශ්‍යය."),
    q("ශ්‍රී ලංකාවේ සාමාන්‍ය විවාහ ආඥාපනත අනුව නීත්‍යානුකූලව විවාහ විය හැකි අවම වයස් සීමාව කීයද?", "අවුරුදු 18", "අවුරුදු 14", "අවුරුදු 16", "අවුරුදු 21", "ළමා විවාහ වැළැක්වීම සඳහා ස්ත්‍රී පුරුෂ දෙපාර්ශ්වයේම අවම විවාහ වයස අවුරුදු 18ක් ලෙස නීතිගත කර ඇත."),
    q("අනාථ, අසරණ හෝ නීතිය සමඟ ගැටුණු දරුවන් රැකබලා ගැනීම හා පුනරුත්ථාපනය සිදුකරන රජයේ දෙපාර්තමේන්තුව කුමක්ද?", "පරිවාස හා ළමාරක්ෂක සේවා දෙපාර්තමේන්තුව", "මෝටර් රථ ප්‍රවාහන දෙපාර්තමේන්තුව", "විභාග දෙපාර්තමේන්තුව", "ආගමන විගමන දෙපාර්තමේන්තුව", "අවදානමට ලක්වූ ළමුන්ට ළමා නිවාස, පරිවාස රැකවරණය හා පුනරුත්ථාපනය මෙම දෙපාර්තමේන්තුවෙන් සපයයි."),
    q("ශ්‍රී ලංකාවේ ළමා හිංසනයක් හෝ අපයෝජනයක් සිදුවන බව දුටු විගස ක්ෂණිකව දැනුම් දිය හැකි පැය 24 නොමිලේ දුරකථන අංකය කුමක්ද?", "1929", "119 පමණක්", "1919", "1900", "ජාතික ළමා ආරක්ෂක අධිකාරියේ 1929 ළමා උපකාරක දුරකථන සේවය භාෂා තුනෙන්ම ක්‍රියාත්මක වේ."),
    q("පවුල තුළ සිදුවන කායික, මානසික හා ආර්ථික හිංසනවලින් කාන්තාවන් හා දරුවන් ආරක්ෂා කිරීමට 2005 දී සම්මත කළ පනත කුමක්ද?", "ගෘහස්ථ ප්‍රචණ්ඩත්වය වැළැක්වීමේ පනත", "කම්කරු වන්දි පනත", "සමාගම් පනත", "පළාත් පාලන පනත", "2005 අංක 34 පනත මඟින් හිංසනකරුගෙන් වින්දිතයා ආරක්ෂා කිරීමට මහේස්ත්‍රාත් අධිකරණයෙන් ආරක්ෂණ ආඥා ලබාගත හැක."),
    q("ශ්‍රී ලංකාවේ වැඩිහිටි පුරවැසියන්ගේ සුබසාධනය හා දරුවන්ගෙන් නඩත්තු ලැබීමේ අයිතිය තහවුරු කරන 2000 අංක 9 දරන පනත කුමක්ද?", "වැඩිහිටි තැනැත්තන්ගේ අයිතිවාසිකම් ආරක්ෂා කිරීමේ පනත", "මැතිවරණ පනත", "පාරිභෝගික අධිකාරි පනත", "විශ්වවිද්‍යාල පනත", "අසරණ වූ මව්පියන්ට දරුවන්ගෙන් නඩත්තු ලබාගැනීමට හා වැඩිහිටි ගෞරවය රැකීමට මෙම පනත ක්‍රියා කරයි."),
    q("පුද්ගලයෙකුගේ ජාතිය, ආගම හෝ සමේ පැහැය මත පදනම්ව පහත් කොට සැලකීම තහනම් කරන එක්සත් ජාතීන්ගේ සම්මුතිය කුමක්ද?", "සියලු ආකාරයේ වාර්ගික වෙනස්කම් තුරන් කිරීමේ සම්මුතිය (ICERD)", "ජාත්‍යන්තර මූල්‍ය අරමුදල් ගිවිසුම", "සමුද්‍ර නීති සම්මුතිය", "ගුවන් සේවා සම්මුතිය", "1965 දී සම්මත වූ ICERD සම්මුතිය වර්ගවාදය හා වාර්ගික වෛරය ප්‍රතික්ෂේප කරයි."),
    q("මූලික අයිතිවාසිකම් ආරක්ෂා කිරීමේදී අධිකරණයේ මූලික කාර්යභාරය කුමක්ද?", "විධායකයේ නීතිවිරෝධී ක්‍රියා අවලංගු කර පුරවැසි අයිතීන් බලාත්මක කිරීම", "පනත් කෙටුම්පත් ලියා පාර්ලිමේන්තුවට යැවීම", "වරිපනම් බදු එකතු කිරීම", "මැතිවරණ දිනය ප්‍රකාශ කිරීම", "අධිකරණය ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ හා මූලික අයිතිවාසිකම්වල උත්තරීතර ආරක්ෂකයා ලෙස කටයුතු කරයි."),
    q("මානව හිමිකම් පිළිබඳ විශ්ව ප්‍රකාශනයේ 29 වන වගන්තිය මඟින් විශේෂයෙන්ම අවධාරණය කර ඇත්තේ කුමක්ද?", "සෑම පුද්ගලයෙකුටම තමා ජීවත් වන ප්‍රජාව කෙරෙහි යුතුකම් පවතින බව", "රජය කිසිදු බද්දක් අය නොකළ යුතු බව", "දරුවන් පාසල් නොයා යුතු බව", "සියලු අයිතීන් අසීමිත බව", "පුද්ගල පෞරුෂය නිදහසේ වර්ධනය වන ප්‍රජාව කෙරෙහි යුතුකම් ඉටු කිරීම UDHR 29 වන වගන්තියෙන් පෙන්වා දේ."),
    q("මහජන සෞඛ්‍යය ආරක්ෂා කිරීම සඳහා ඩෙංගු මදුරුවන් බෝවන ස්ථාන ඉවත් කරමින් ගෙවත්ත පිරිසිදුව තබාගැනීම කුමන යුතුකමක්ද?", "සමාජ වගකීම හා සෞඛ්‍යාරක්ෂිත පුරවැසි යුතුකම", "අධිකරණ වරප්‍රසාදය", "විධායක බලය", "ඡන්දදායක අයිතිය", "තමාගේ පරිසරය පිරිසිදුව තබාගැනීමෙන් අසල්වැසියන්ගේ ජීවිත හා සෞඛ්‍යයද සුරැකේ."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක පුරවැසියන් රාජ්‍ය දේපළ වන බස් රථ, දුම්රිය හා පොදු ගොඩනැගිලි ආරක්ෂා කළ යුත්තේ ඇයි?", "ඒවා සියලු පුරවැසියන්ගේ බදු මුදලින් නඩත්තු වන පොදු සම්පත් නිසාය", "ඒවා විදේශීය සමාගම්වලට අයත් නිසාය", "ඒවා රජයේ මැති ඇමතිවරුන්ගේ පෞද්ගලික දේපළ නිසාය", "විරෝධතාවලදී විනාශ කිරීම සඳහාම නිසාය", "පොදු දේපළවලට හානි කිරීමෙන් අහිමි වන්නේ මහජනතාවගේම සේවා පහසුකම් හා රටේ සම්පත්ය."),
    q("විරෝධතාවක් හෝ වැඩවර්ජනයක් පවත්වන අවස්ථාවකදී පුරවැසියන් අනිවාර්යයෙන්ම ගරු කළ යුතු සීමාව කුමක්ද?", "සාමකාමී බව රැකීම හා අනෙක් පුරවැසියන්ගේ ජීවිතවලට හෝ දේපළවලට හානි නොකිරීම", "පොදු රෝහල්වල විදුලිය විසන්ධි කිරීම", "පාසල් බස් රථවලට ගල් ගැසීම", "රාජ්‍ය ලේඛන ගිනි තැබීම", "විරෝධය පෑමේ අයිතිය ඇතත් ප්‍රචණ්ඩ ක්‍රියා හා දේපළ හානි ප්‍රජාතන්ත්‍රවාදී නීතියෙන් තහනම්ය."),
    q("ඩිජිටල් ලෝකයේදී අන් අයගේ මූල්‍ය හෝ පෞද්ගලික තොරතුරු සොරකම් කිරීම හා අන්තර්ජාලයෙන් හිංසා කිරීම වැළැක්වීමේ නීතිය කුමක්ද?", "2007 අංක 24 දරන පරිගණක අපරාධ පනත", "1947 රාජ්‍ය සේවා පනත", "1988 පළාත් සභා පනත", "1972 ජනරජ ව්‍යවස්ථාව", "සයිබර් හිංසන, අනවසර පිවිසුම් හා දත්ත සොරකම් 2007 පරිගණක අපරාධ පනත යටතේ දඬුවම් ලැබිය හැකි වැරදිය."),
    q("පුද්ගලයෙකුගේ 'ප්‍රකාශන අයිතිය' ආරක්ෂා වන අතරම පොදු ජනතාවට ව්‍යාජ පුවත්වලින් හානි වීම වැළැක්වීමට ගත හැකි හොඳම පුරවැසි පියවර කුමක්ද?", "තොරතුරක සත්‍ය අසත්‍ය බව තහවුරු නොකර හුවමාරු කිරීමෙන් වැළකීම", "සියලු ප්‍රවෘත්ති කියවීම නතර කිරීම", "පුවත්පත් ආයතන වසා දැමීම", "අන්තර්ජාලය සදහටම තහනම් කිරීම", "විශ්වාසනීය මූලාශ්‍රවලින් තොරතුරු පරීක්ෂා කිරීම වගකීම්සහගත ඩිජිටල් පුරවැසියෙකුගේ ලක්ෂණයකි."),
    q("1978 ව්‍යවස්ථාවේ 12(1) වගන්තිය යටතේ 'සාධාරණ වර්ගීකරණය' (Reasonable Classification) යන්නෙන් අධිකරණය පිළිගන්නේ කුමක්ද?", "පැහැදිලි හා යුක්තිසහගත අරමුණක් මත පදනම්ව විශේෂ කණ්ඩායම්වලට වෙනස් පහසුකම් සැලසීම", "ඕනෑම අයෙකුට හිතූ පරිදි වෙනස්කම් කිරීම", "ඥාතීන්ට පමණක් රැකියා ලබාදීම", "එක් ජනවර්ගයකට පමණක් ඡන්ද බලය දීම", "උදාහරණයක් ලෙස ආදායම අනුව ශිෂ්‍යාධාර දීම අසාධාරණ වෙනස්කමක් නොව සාධාරණ වර්ගීකරණයකි."),
    q("මූලික අයිතිවාසිකම්වලට පටහැනි ලෙස රජයේ ආයතනයක් කටයුතු කළ විට පුරවැසියාට අධිකරණයෙන් ඉල්ලා සිටිය හැකි සහනයක් නොවන්නේ කුමක්ද?", "එම ආයතනයේ සභාපතිවරයාට මරණ දඬුවම නියම කිරීම", "අයිතිය කඩවූ බවට ප්‍රකාශයක් ලබාගැනීම", "සිදුවූ අගතිය වෙනුවෙන් මූල්‍ය වන්දි ලබාගැනීම", "අසාධාරණ තීරණය අවලංගු කරගැනීම", "126 වගන්තිය සිවිල් ආණ්ඩුක්‍රම ව්‍යවස්ථා සහනයක් මිස මරණ දඬුවම් දෙන අපරාධ නඩු ක්‍රමයක් නොවේ."),
    q("ශ්‍රී ලංකාවේ දේශීය හා විදේශීය රැකියාවල නිරත ශ්‍රමිකයන්ගේ මානව හිමිකම් රැකීමට ක්‍රියා කරන ප්‍රධාන ජාත්‍යන්තර සංවිධානය කුමක්ද?", "ජාත්‍යන්තර කම්කරු සංවිධානය (ILO)", "ජාත්‍යන්තර පරමාණුක බලශක්ති ඒජන්සිය", "ජාත්‍යන්තර ඔලිම්පික් කමිටුව", "ලෝක තැපැල් සංගමය", "වැඩබිම් ආරක්ෂාව, සේවා කොන්දේසි හා වෘත්තීය අයිතීන් සඳහා ILO ප්‍රමිතීන් නියම කරයි."),
    q("විදේශ රැකියා සඳහා පිටත්වන ශ්‍රී ලාංකික ශ්‍රමිකයන්ගේ අයිතිවාසිකම් හා සුබසාධනය භාර දේශීය රාජ්‍ය ආයතනය කුමක්ද?", "ශ්‍රී ලංකා විදේශ සේවා නියුක්ති කාර්යාංශය", "මහා භාණ්ඩාගාරය", "ශ්‍රී ලංකා මහ බැංකුව", "විශ්වවිද්‍යාල ප්‍රතිපාදන කොමිසම", "විදේශගත ශ්‍රමිකයන් ලියාපදිංචි කිරීම, රක්ෂණය හා ගැටලු විසඳීම මෙම කාර්යාංශයේ කාර්යයකි."),
    q("පාරිභෝගිකයෙකු ලෙස කල් ඉකුත් වූ ආහාරපාන ප්‍රතික්ෂේප කිරීමට හා ගුණාත්මක භාණ්ඩ ඉල්ලා සිටීමට ඇති අයිතිය සුරකින රාජ්‍ය ආයතනය කුමක්ද?", "පාරිභෝගික කටයුතු පිළිබඳ අධිකාරිය", "පරිවාස දෙපාර්තමේන්තුව", "මැතිවරණ කොමිසම", "රාජ්‍ය භාෂා කොමිසම", "2003 අංක 9 දරන පනත යටතේ පාරිභෝගිකයන්ගේ ආරක්ෂාව හා සාධාරණ වෙළඳාම අධීක්ෂණය කෙරේ."),
    q("මහමග ගමන් කිරීමේදී පදික මාරුවෙන් පාර මාරු වීම සහ රථවාහන සංඥාවලට ගරු කිරීම පුරවැසියාගේ කුමන යුතුකමද?", "රටේ පොදු නීතියට අවනත වී ජීවිත ආරක්ෂා කිරීමේ යුතුකම", "ව්‍යවස්ථාදායක බලය භාවිත කිරීම", "විදේශ ප්‍රතිපත්තිය සැකසීම", "අධිකරණ සේවා කොමිසම පාලනය කිරීම", "මාර්ග නීති පිළිපැදීම අපගේත් අන් අයගේත් ජීවත්වීමේ අයිතිය ආරක්ෂා කරන මූලික යුතුකමකි."),
    q("පුද්ගලයෙකුට අධිකරණයේදී 'ද්විත්ව අනතුරෙන් නිදහස් වීම' (Double Jeopardy) යන්නෙන් ලැබෙන නීතිමය ආරක්ෂාව කුමක්ද?", "එකම වරදක් සඳහා දෙවරක් නඩු පවරා දඬුවම් නොකිරීම", "නීතිඥයන් දෙදෙනෙකු පත් කිරීම", "අභියාචනා දෙකක් ඉදිරිපත් කිරීම", "දෙගුණයක දඩ මුදලක් ගෙවීම", "එක් වරක් විධිමත් අධිකරණයකින් නිදහස් කළ හෝ දඬුවම් කළ වරදකට යළිත් නඩු පැවරීම නීතියෙන් තහනම්ය."),
    q("සාමකාමී හා ශිෂ්ටසම්පන්න සමාජයක් ගොඩනැගීම සඳහා 'අයිතිවාසිකම් හා යුතුකම් අතර සමබරතාවක්' පැවතිය යුත්තේ ඇයි?", "යුතුකම් ඉටු නොකර අයිතීන් පමණක් ඉල්ලුවහොත් සමාජ අරාජිකත්වය ඇතිවන බැවිනි", "අයිතිවාසිකම් වැඩි වීමෙන් රජයේ ආදායම අඩු වන බැවිනි", "යුතුකම් අධිකරණයෙන් පමණක් ක්‍රියාත්මක වන බැවිනි", "පුරවැසියන්ට අයිතිවාසිකම් අනවශ්‍ය බැවිනි", "සෑම පුරවැසියෙකුම තම යුතුකම් ඉටු කරන විට අනෙක් සියල්ලන්ගේම අයිතිවාසිකම් ඉබේම සුරක්ෂිත වේ."),
    q("1978 ව්‍යවස්ථාවේ 13(3) වගන්තිය අනුව නඩු විභාගයකදී 'සාධාරණ නඩු විභාගයක' (Fair Trial) අත්‍යවශ්‍ය අංගයක් වන්නේ කුමක්ද?", "තමාගේම වියදමින් හෝ නීති ආධාරයෙන් නීතිඥයෙකු මඟින් කරුණු දැක්වීමට ඉඩ ලැබීම", "පැමිණිලිකරුගේ සාක්ෂි රහසිගතව තැබීම", "විත්තිකරුට කතා කිරීමට ඉඩ නොදීම", "නඩුව විභාග නොකරම දඬුවම් දීම", "චෝදනාවට පිළිතුරු දීමට ප්‍රමාණවත් කාලය හා නීතිඥ සහාය සාධාරණ නඩු විභාගයක හරයයි."),
    q("ශ්‍රී ලංකාවේ ළමා අයිතිවාසිකම් ක්ෂේත්‍රයේ පාසල් දරුවන් පාසල් නොයවා ගෘහ සේවයේ යොදාගැනීම වළක්වන්නේ කුමන නීතිමය සීමාවෙන්ද?", "ළමා ශ්‍රමය තහනම් කිරීමේ කම්කරු හා අනිවාර්ය අධ්‍යාපන නීති", "ව්‍යාපාරික බදු ආඥාපනත", "මැතිවරණ කොමිෂන් නීති", "විදේශ විනිමය පනත", "වයස 16ට අඩු දරුවන් සේවයේ යෙදවීම තහනම් කර අධ්‍යාපන අයිතිය තහවුරු කිරීමට නීති පනවා ඇත."),
    q("සංස්කෘතික හා ආගමික විවිධත්වයක් ඇති ශ්‍රී ලංකාවේ පුරවැසියන් විසින් අන් අයගේ ආගමික ස්ථාන හා උත්සව කෙරෙහි දැක්විය යුතු ආකල්පය කුමක්ද?", "ගෞරවය, ඉවසීම හා සහයෝගීතාව දැක්වීම", "තම ආගමට පමණක් වරප්‍රසාද ඉල්ලීම", "අනෙක් ආගමික උත්සවවලට බාධා කිරීම", "සංස්කෘතික උත්සව තහනම් කිරීම", "සියලු ආගම් හා සංස්කෘතීන්ට සමාන ගෞරවය දැක්වීමෙන් ජාතික සංහිඳියාව හා සමානාත්මතාව රැකේ."),
    q("රටේ ජාතික සංවර්ධනය උදෙසා 'කාලය, ශ්‍රමය හා දැනුම නිසි ලෙස යෙදවීම' වැදගත් වන්නේ කුමන වගකීමක් ලෙසද?", "තමන්ටත් රටටත් යුතුකම් ඉටු කරන ඵලදායී පුරවැසියෙකු වීමේ වගකීම", "විධායක ජනාධිපති බලතල ක්‍රියාත්මක කිරීම", "පළාත් සභා ආදායම් බෙදීම", "අධිකරණ රීට් ආඥා නිකුත් කිරීම", "ව්‍යවස්ථාවේ 28(ඈ) වගන්තිය අනුව තමා තෝරාගත් වෘත්තියෙහි හෘදය සාක්ෂියට අනුව කැපවීමෙන් වැඩ කිරීම යුතුකමකි."),
    q("මහජන සේවා ලබාගැනීමේදී පෝලිමක රැඳී සිටීම සහ රෝගීන්ට හා ගැබිනි මව්වරුන්ට ප්‍රමුඛතාව ලබාදීම ප්‍රකට කරන්නේ කුමක්ද?", "සමාජ විනය සහ මානව ගරුත්වයට ගරු කිරීම", "පරිපාලන අකාර්යක්ෂමතාව", "ව්‍යවස්ථාදායක මුක්තිය", "ආර්ථික තරගකාරිත්වය", "පොදු ස්ථානවල විනයගරුක හා සංවේදී හැසිරීම සමාජ සාධාරණත්වය හා සමානාත්මතාව පිළිබිඹු කරයි."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක ජනමාධ්‍යවේදීන්ට තම ආරංචි මාර්ග රහසිගතව තබාගැනීමට හා සත්‍ය තොරතුරු වාර්තා කිරීමට ඇති නිදහස අයත් වන්නේ කුමන අයිතියටද?", "භාෂණයේ හා ප්‍රකාශනයේ නිදහස සහ මාධ්‍ය නිදහස", "රහස් ඡන්ද අයිතිය", "විදේශ ගමන් නිදහස", "ආගමික නිදහස", "තොරතුරු ගවේෂණය කර ජනතාව දැනුවත් කිරීමේ මාධ්‍ය නිදහස ප්‍රකාශන අයිතියේ ප්‍රබල අංගයකි."),
    q("ශ්‍රී ලංකාවේ 1978 ව්‍යවස්ථාවේ 14(1)(ඌ) වගන්තිය අනුව රජයට පුරවැසියෙකුගේ රට තුළ ගමන් බිමන් යාම සීමා කළ හැක්කේ කවර විශේෂ හේතු මතද?", "ජාතික ආරක්ෂාව, මහජන සාමය හා ජාතික ආර්ථිකය වෙනුවෙන් පනවන නීතියකින්", "පුරවැසියාගේ ආදායම අඩු වූ විට", "දේශපාලන පක්ෂයක් මාරු කළ විට", "වෙනත් භාෂාවක් කතා කළ විට", "වසංගත නිරෝධායන හෝ ආරක්ෂක කලාප වැනි නීතිමය අවස්ථාවලදී 15(6) හා 15(7) යටතේ සීමා පැනවිය හැක."),
    q("රටේ පාසල් අධ්‍යාපන පද්ධතිය තුළ නොමිලේ පෙළපොත්, නිල ඇඳුම් හා දිවා ආහාරය සැපයීම මඟින් ඉටු කරන්නේ කුමන අයිතිවාසිකමද?", "සෑම දරුවෙකුටම අධ්‍යාපනයට සමාන ප්‍රවේශයක් ලබාදීමේ අයිතිය", "දේපළ බදු අඩු කිරීමේ අයිතිය", "වෘත්තීය සමිති පිහිටුවීමේ අයිතිය", "අධිකරණ අභියාචනා අයිතිය", "ආර්ථික දුෂ්කරතා නිසා දරුවෙකුගේ අධ්‍යාපනය නොකඩවා රැකගැනීම සමානාත්මතාව හා ළමා සංවර්ධන අයිතිය තහවුරු කරයි."),
    q("විශ්ව මානව හිමිකම් ප්‍රකාශනයේ 2 වන වගන්තිය අනුව මානව හිමිකම් භුක්ති විඳීමේදී ප්‍රතික්ෂේප කරන දෙය කුමක්ද?", "ජාති, වර්ණ, ලිංග, භාෂා, ආගම් හෝ දේශපාලන මත මත වෙනස්කම් කිරීම", "නීතියට අවනත වීම", "සමාජ සුබසාධනය", "පරිසර සංරක්ෂණය", "මානව හිමිකම් විශ්වීය වන අතර කිසිදු පුද්ගලයෙකු උපත හෝ මතය මත කොන් නොකළ යුතු බව 2 වගන්තිය කියයි."),
    q("මානව හිමිකම් උල්ලංඝනය වීමක් වැළැක්වීම සඳහා පුරවැසියෙකු අනුගමනය කළ යුතු වඩාත්ම ශිෂ්ටසම්පන්න ක්‍රියාමාර්ගය කුමක්ද?", "නීත්‍යානුකූලව මානව හිමිකම් කොමිසම, අධිකරණය හෝ පොලිසිය මඟින් ප්‍රතිකාර පැතීම", "ප්‍රචණ්ඩ ලෙස නීතිය අතට ගැනීම", "පොදු දේපළ ගිනි තැබීම", "පාසල් වර්ජනය කර මාර්ග අවහිර කිරීම", "මානව හිමිකම් රැකෙන්නේ හිංසනයෙන් නොව ප්‍රජාතන්ත්‍රවාදී හා නීතිමය යාන්ත්‍රණ භාවිත කිරීමෙනි."),
    q("ශ්‍රී ලංකාවේ 'රාජ්‍ය සේවකයන්ගේ දේශපාලන මධ්‍යස්ථභාවය' රැකීම සඳහා ඇති සීමාව අවශ්‍ය වන්නේ ඇයි?", "සියලු පුරවැසියන්ට දේශපාලන භේදයකින් තොරව අපක්ෂපාතී රාජ්‍ය සේවයක් සැලසීමට", "රජයේ කාර්යාල නිවාඩු වැඩි කිරීමට", "රාජ්‍ය සේවකයන්ට ඡන්ද බලය නැති කිරීමට", "පළාත් සභා මුදල් අඩු කිරීමට", "උසස් රාජ්‍ය නිලධාරීන් පක්ෂ දේශපාලනයෙන් තොරව කටයුතු කිරීම 12(1) සමානාත්මතාව රකී."),
    q("එක්සත් ජාතීන්ගේ ළමා අයිතිවාසිකම් ප්‍රඥප්තිය යටතේ දරුවෙකු සතු 'විවේකය, ක්‍රීඩාව හා සංස්කෘතික ජීවිතයට සහභාගී වීමේ අයිතිය' දැක්වෙන්නේ කුමන වගන්තියේද?", "31 වන වගන්තිය", "1 වන වගන්තිය", "40 වන වගන්තිය", "54 වන වගන්තිය", "UNCRC 31 වන වගන්තිය දරුවන්ට වයසට සරිලන විවේකය, ක්‍රීඩාව හා කලා කටයුතුවල නිරත වීමේ අයිතිය පිළිගනී."),
    q("යම් රැකියා ස්ථානයක සේවකයන්ට අවම වැටුප, සේවක අර්ථසාධක අරමුදල (EPF) හා නිවාඩු හිමිකම් ලබාදීම රකින්නේ කුමන අයිතීන්ද?", "ආර්ථික හා සමාජීය කම්කරු අයිතිවාසිකම්", "රහස් ඡන්ද අයිතිවාසිකම්", "අධිකරණ රීට් අයිතිවාසිකම්", "විදේශ තානාපති අයිතිවාසිකම්", "සාධාරණ සේවා කොන්දේසි හා සමාජ ආරක්ෂණය දෙවන පරම්පරාවේ ආර්ථික අයිතිවාසිකම් වේ."),
    q("පාසලක ශිෂ්‍ය පාර්ලිමේන්තුවක් හෝ ශිෂ්‍ය නායක මණ්ඩලයක් පිහිටුවීමෙන් දරුවන්ට පුහුණු කෙරෙන ප්‍රධාන ප්‍රජාතන්ත්‍රවාදී ගුණාංගය කුමක්ද?", "නායකත්වය, වගවීම සහ අයිතිවාසිකම් සමඟ යුතුකම් පුරුදු පුහුණු වීම", "විභාග ප්‍රශ්න පත්‍ර සකස් කිරීම", "පාසල් ගොඩනැගිලි බදු දීම", "මැතිවරණ නීති අවලංගු කිරීම", "කුඩා කල සිටම ප්‍රජාතන්ත්‍රවාදී සංවාදය, සාමූහික තීරණ හා වගකීම් දැරීම ශිෂ්‍ය පාර්ලිමේන්තුවෙන් පුහුණු කෙරේ."),
    q("අපරාධයකට සැකපිට අත්අඩංගුවට ගත් තැනැත්තෙකුට 'නිහඬව සිටීමේ අයිතිය' වැදගත් වන්නේ ඇයි?", "තමාට එරෙහිව බලහත්කාරයෙන් සාක්ෂි ලබාගැනීම වැළැක්වීමට", "අධිකරණයට නොගොස් ගෙදර යාමට", "විනිසුරුට අපහාස කිරීමට", "නීතිඥයා ඉවත් කිරීමට", "චූදිතයෙකු ලවා බලෙන් වරද පිළිගැන්වීම වැළැක්වීම සාධාරණ යුක්තිය පසිඳලීමේ මූලධර්මයකි."),
    q("විශ්ව මානව හිමිකම් ප්‍රකාශනය පළමු වරට එක්සත් ජාතීන්ගේ මහා මණ්ඩලය මඟින් සම්මත කරගත් ස්ථානය කුමක්ද?", "ප්‍රංශයේ පැරිස් නුවර (පැලේ ඩි ෂයියෝ)", "ඇමරිකාවේ නිව්යෝර්ක් නුවර", "එංගලන්තයේ ලන්ඩන් නුවර", "ජපානයේ ටෝකියෝ නුවර", "1948 දෙසැම්බර් 10 දින පැරිස් නුවර පැවති එක්සත් ජාතීන්ගේ මහා මණ්ඩල සැසියේදී UDHR සම්මත විය."),
    q("කිසියම් පුද්ගලයෙකු රජයේ රෝහලකට හෝ පොදු සෞඛ්‍ය මධ්‍යස්ථානයකට ප්‍රතිකාර සඳහා පැමිණි විට ජාති ආගම් භේදයකින් තොරව ප්‍රතිකාර ලැබීම පිළිබිඹු කරන්නේ කුමක්ද?", "සෞඛ්‍ය අයිතිය හා සමානාත්මතාව", "ව්‍යාපාරික ඒකාධිකාරය", "දේශපාලන මුක්තිය", "විමධ්‍යගත බදු ක්‍රමය", "සෑම පුරවැසියෙකුටම සමානව සෞඛ්‍ය සේවා ප්‍රවේශය ලැබීම මානව අයිතියකි."),
    q("දේශීය හා ගෝලීය වශයෙන් 'මානව හිමිකම් අධ්‍යාපනය' පාසල් විෂය මාලාවට ඇතුළත් කිරීමේ අරමුණ කුමක්ද?", "අයිතීන් හඳුනාගන්නා අතරම අන් අයගේ අයිතීන්ට ගරු කරන පුරවැසියන් බිහි කිරීම", "නීතිඥයන්ගේ ආදායම අඩු කිරීම", "මැතිවරණ වයස වැඩි කිරීම", "අධිකරණ සංඛ්‍යාව අඩු කිරීම", "මානව හිමිකම් ගැන දැනුවත් සමාජයක් තුළ ප්‍රචණ්ඩත්වය හා වෙනස්කම් කිරීම් අවම වේ."),
    q("ශ්‍රී ලංකාවේ 1978 ව්‍යවස්ථාවේ 14(1)(අ) වගන්තියෙන් ප්‍රකාශන නිදහස ලබා දී තිබුණද 'ජාතික හා ආගමික සමගියට හානි වන වෛරී ප්‍රකාශ' පාලනය කිරීමට හේතුව කුමක්ද?", "බහුසංස්කෘතික සමාජයක සාමය හා සෙසු පුරවැසියන්ගේ අයිතීන් ආරක්ෂා කිරීම", "පුවත්පත් කියවීම තහනම් කිරීම", "රාජ්‍ය භාෂා අහෝසි කිරීම", "ඡන්දදායක සංඛ්‍යාව අඩු කිරීම", "15(2) වගන්තිය හා ICCPR පනත මඟින් වාර්ගික හා ආගමික ප්‍රචණ්ඩත්වය ඇවිස්සීම වළක්වා ඇත."),
    q("විශේෂ අවශ්‍යතා ඇති දරුවන්ට සාමාන්‍ය පාසල් පද්ධතිය තුළම ඉගෙනීමට අවස්ථා සැලසීමේ සංකල්පය හඳුන්වන්නේ කෙසේද?", "අන්තර්කරණ අධ්‍යාපනය (Inclusive Education)", "විශේෂ බදු අධ්‍යාපනය", "සීමිත වෘත්තීය අධ්‍යාපනය", "පෞද්ගලික වාණිජ අධ්‍යාපනය", "ආබාධ සහිත දරුවන් කොන් නොකර සෙසු දරුවන් සමඟ ඉගෙනීමේ සමාන අයිතිය තහවුරු කිරීම මෙහි අරමුණයි."),
    q("මානව හිමිකම් පිළිබඳව සැලකීමේදී 'නීත්‍යානුකූල නොවන ලෙස පුද්ගලයෙකුගේ නිවසට ඇතුළු වීම හෝ පෞද්ගලික ලිපි විවෘත කිරීම' උල්ලංඝනය කරන්නේ කුමක්ද?", "පෞද්ගලිකත්වයට හා පවුලේ ගෞරවයට ඇති අයිතිය", "රහස් ඡන්ද අයිතිය", "වෘත්තීය සමිති අයිතිය", "බදු නිදහස් අයිතිය", "UDHR 12 වන වගන්තිය මඟින් පුද්ගලයාගේ පෞද්ගලික ජීවිතය, පවුල හා නිවස ආරක්ෂා කර ඇත."),
    q("සෑම පුරවැසියෙකුම තමාගේ රටේ ජාතික ධජයට, ජාතික ගීයට හා ආණ්ඩුක්‍රම ව්‍යවස්ථාවට ගරු කළ යුතු බව දැක්වෙන්නේ 1978 ව්‍යවස්ථාවේ කුමන වගන්තියේද?", "28(අ) වගන්තිය", "10 වගන්තිය", "13(1) වගන්තිය", "126 වගන්තිය", "28(අ) වගන්තිය අනුව ව්‍යවස්ථාව හා ජාතික ආයතන කෙරෙහි ගෞරවයෙන් කටයුතු කිරීම පුරවැසි යුතුකමකි."),
    q("මහජනතාව වෙත තොරතුරු ලබාදීම ප්‍රතික්ෂේප කළ රාජ්‍ය ආයතනයකට එරෙහිව 14අ අයිතිය ක්‍රියාත්මක කිරීමට පැමිණිලි කළ හැකි ආයතනය කුමක්ද?", "තොරතුරු දැනගැනීමේ අයිතිවාසිකම පිළිබඳ කොමිෂන් සභාව", "සුරාබදු දෙපාර්තමේන්තුව", "පළාත් පාලන කොමසාරිස් කාර්යාලය", "විශ්වවිද්‍යාල ප්‍රතිපාදන කොමිසම", "රාජ්‍ය ආයතනයකින් තොරතුරු ලබාදීම පැහැර හැරියහොත් RTI කොමිෂන් සභාවට අභියාචනා කළ හැක."),
    q("ප්‍රජාතන්ත්‍රවාදී සමාජයක සාමූහික යහපත උදෙසා 'ප්‍රචණ්ඩත්වයෙන් තොරව ආරවුල් විසඳාගැනීම' වැදගත් වන්නේ ඇයි?", "සියලු පුරවැසියන්ගේ ජීවත්වීමේ අයිතිය හා මානව ගරුත්වය රැකෙන බැවිනි", "අධිකරණ පද්ධතිය වසා දැමීමට හැකි වන බැවිනි", "විදේශීය ණය ප්‍රමාණය අඩු වන බැවිනි", "මැතිවරණ පැවැත්වීම අනවශ්‍ය වන බැවිනි", "සංවාදය හා නීතිය තුළින් ගැටලු විසඳීම මානව හිමිකම් සුරැකෙන සාමකාමී සමාජයක පදනමයි."),
    q("අපරාධ චෝදනාවකට ලක්වූ පුද්ගලයෙකුට අධිකරණයෙන් දඬුවම් නියම කිරීමේදී 'අනුපාතිකත්වය' (Proportionality) යන්නෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "වරදේ බරපතළකමට සරිලන සාධාරණ දඬුවමක් පමණක් නියම කිරීම", "ඕනෑම සුළු වරදකට මරණ දඬුවම දීම", "ධනවතුන්ට පමණක් දඩ නියම කිරීම", "වරදකරුගේ මුළු පවුලටම දඬුවම් කිරීම", "සුළු වරදකට අතිශය කෲර දඬුවම් නොදී යුක්තිසහගත අනුපාතයකින් දඬුවම් දීම මානව හිමිකම් මූලධර්මයකි."),
    q("ශ්‍රී ලංකාවේ ළමා හිමිකම් ක්ෂේත්‍රයේ 'ජාතික ළමා දිනය' ලෙස සෑම වසරකම සමරනු ලබන දිනය කුමක්ද?", "ඔක්තෝබර් 01", "මැයි 01", "පෙබරවාරි 04", "අප්‍රේල් 07", "ලෝක ළමා දිනය සමඟ ශ්‍රී ලංකාවේ ජාතික ළමා දිනය සෑම වසරකම ඔක්තෝබර් 1 දින සැමරේ."),
    q("සෑම වසරකම මාර්තු 08 වන දින ජාත්‍යන්තර වශයෙන් සමරනු ලබන්නේ කුමන අයිතිවාසිකම් දිනයද?", "ජාත්‍යන්තර කාන්තා දිනය", "ජාත්‍යන්තර කම්කරු දිනය", "ජාත්‍යන්තර පරිසර දිනය", "ජාත්‍යන්තර සාම දිනය", "කාන්තාවන්ගේ සමාජ, ආර්ථික හා දේශපාලන සමානාත්මතාව සැමරීමට මාර්තු 8 ජාත්‍යන්තර කාන්තා දිනය නම් කර ඇත."),
    q("ලෝක කම්කරු දිනය සැමරෙන මැයි 01 වන දින ප්‍රධාන වශයෙන් අවධාරණය කරන්නේ කුමන අයිතිවාසිකම්ද?", "වැඩ කරන ජනතාවගේ පැය 8 වැඩ දිනය, සාධාරණ වැටුප් හා සේවා අයිතීන්", "මැතිවරණ කොට්ඨාස සීමා", "තානාපති වරප්‍රසාද", "අධිකරණ විනිසුරු පත්වීම්", "ශ්‍රමිකයන්ගේ ගෞරවය, ආරක්ෂාව හා සාධාරණ වැටුප් අයිතිවාසිකම් මැයි දිනයෙන් සිහිපත් කෙරේ."),
    q("රටේ සංවර්ධන ව්‍යාපෘතියක් හේතුවෙන් තම පාරම්පරික ඉඩම් අහිමි වන පුරවැසියන්ට රජය ලබාදිය යුතු මානව හිමිකම කුමක්ද?", "සාධාරණ වන්දි සහ විකල්ප නැවත පදිංචි කිරීමේ පහසුකම්", "රටින් පිටුවහල් කිරීම", "ඡන්ද බලය අහෝසි කිරීම", "දරුවන්ගේ අධ්‍යාපනය නතර කිරීම", "පොදු කටයුත්තකට ඉඩම් පවරා ගන්නා විට ජනතාවගේ ජීවනෝපාය හා නිවාස අයිතිය වෙනුවෙන් සාධාරණ වන්දි දිය යුතුය."),
    q("1978 ව්‍යවස්ථාවේ 14(1)(ඉ) වගන්තියෙන් ආරක්ෂා වී ඇති ආගමික නිදහස තුළ පාසල් සිසුන් අතර සමගිය වර්ධනය වන්නේ කෙසේද?", "තමාගේ ආගම අදහන අතරම සෙසු මිතුරන්ගේ ආගමික විශ්වාසයන්ටද ගරු කිරීමෙන්", "පාසල්වල ආගමික උත්සව තහනම් කිරීමෙන්", "සියලු දෙනාට එකම ඇඳුමක් බලෙන් ඇන්දවීමෙන්", "ආගමික ග්‍රන්ථ ඉවත් කිරීමෙන්", "විවිධ ආගමික සම්ප්‍රදායන් හඳුනාගෙන අන්‍යෝන්‍ය ගෞරවයෙන් ජීවත් වීම සමාජ සමගිය ශක්තිමත් කරයි."),
    q("රාජ්‍ය පරිපාලනයේදී මහජන පැමිණිලි විභාග කිරීමට 1978 ව්‍යවස්ථාවේ 156 වන වගන්තියෙන් ස්ථාපිත තනතුර කුමක්ද?", "පරිපාලන කටයුතු පිළිබඳ පාර්ලිමේන්තු කොමසාරිස් (ඔම්බුඩ්ස්මන්)", "මැතිවරණ කොමසාරිස් ජනරාල්", "රේගු අධ්‍යක්ෂ ජනරාල්", "විදේශ ලේකම්", "රාජ්‍ය නිලධාරීන් අතින් සිදුවන පරිපාලන අසාධාරණ හා අයිතිවාසිකම් කඩවීම් ඔම්බුඩ්ස්මන්වරයා විමර්ශනය කරයි."),
    q("රටේ පුරවැසියන්ට 'රැකියාවක් කිරීමේ නිදහස' මෙන්ම ව්‍යාපාර පවත්වාගැනීමේදී රජයට බැඳී සිටින ප්‍රධාන යුතුකම කුමක්ද?", "පාරිභෝගික ආරක්ෂාව, පාරිසරික නීති හා නියමිත බදු නීතිවලට අවනත වීම", "සේවකයන්ට වැටුප් නොගෙවා සිටීම", "භාණ්ඩ හිඟයක් මවා පෑම", "අපද්‍රව්‍ය ගංගාවලට මුදා හැරීම", "ව්‍යාපාරික නිදහස භුක්ති විඳීමේදී සමාජයට හා පරිසරයට හානි නොකිරීමේ නීතිමය හා සදාචාර යුතුකම පවතී."),
    q("ජාතික හා ජාත්‍යන්තර මානව හිමිකම් ප්‍රඥප්ති පිළිගැනීමෙන් පසු රාජ්‍යයක් ඉටු කළ යුතු ප්‍රධාන වගකීම කුමක්ද?", "දේශීය නීති පද්ධතිය එම ප්‍රමිතීන්ට ගැළපෙන සේ සකස් කර ක්‍රියාත්මක කිරීම", "ප්‍රඥප්ති කෞතුකාගාරවල තැන්පත් කිරීම", "පාර්ලිමේන්තුව විසුරුවා හැරීම", "අධිකරණ බලය සීමා කිරීම", "අපරානුමත කරන ලද ජාත්‍යන්තර සම්මුතීන් දේශීය පනත් මඟින් බලාත්මක කිරීම රජයේ වගකීමකි."),
    q("ශ්‍රී ලංකාවේ ළමා අයිතිවාසිකම් හා සුබසාධනය වෙනුවෙන් පාසල් මට්ටමින් ක්‍රියාත්මක වන ව්‍යවස්ථාපිත අරමුණ කුමක්ද?", "කිසිදු දරුවෙකු දුප්පත්කම හෝ ආබාධිත බව නිසා පාසල් අධ්‍යාපනයෙන් මඟ නොහැරීම", "ක්‍රීඩා කටයුතු සම්පූර්ණයෙන් නතර කිරීම", "සෑම වසරකම පාසල් නිවාඩු දින අඩු කිරීම", "විභාග ගාස්තු දස ගුණයකින් වැඩි කිරීම", "සැමට සමාන අධ්‍යාපන අයිතිය (Education for All) තහවුරු කිරීම ප්‍රජාතන්ත්‍රවාදී රාජ්‍ය ප්‍රතිපත්තියයි."),
    q("රටේ ව්‍යවස්ථාවේ මූලික අයිතිවාසිකම් පරිච්ඡේදය (10–17) සංශෝධනය කිරීමේදී විශේෂ ආරක්ෂාවක් ලබා දී ඇති වගන්ති දෙකක් මොනවාද?", "10 සහ 11 වන වගන්ති (සංශෝධනයට 2/3 හා ජනමත විචාරණය අවශ්‍ය වේ)", "28 සහ 29 වගන්ති", "156 සහ 157 වගන්ති", "42 සහ 43 වගන්ති", "83 වන වගන්තිය අනුව 10 හා 11 වගන්ති සංශෝධනය කිරීමට 2/3 බහුතරය හා ජනමත විචාරණයක් අනිවාර්ය වේ."),
    q("පුද්ගලයෙකුගේ 'නිවසක් හිමිවීමේ හා ප්‍රමාණවත් ජීවන තත්ත්වයක් ලැබීමේ අයිතිය' ඇතුළත් ජාත්‍යන්තර ලේඛනය කුමක්ද?", "විශ්ව මානව හිමිකම් ප්‍රකාශනය (25 වගන්තිය) සහ ICESCR", "ජිනීවා යුද සම්මුතිය", "සමුද්‍ර නීති ප්‍රඥප්තිය", "බැන්ඩුං ප්‍රකාශනය", "ආහාර, ඇඳුම් පැළඳුම්, නිවාස හා වෛද්‍ය සත්කාර ලැබීමේ අයිතිය UDHR 25 වගන්තියේ සඳහන් වේ."),
    q("පුරවැසියෙකු තමා ජීවත් වන ප්‍රජාව තුළ 'සමාන අයිතීන් හා යුතුකම්' සමතුලිතව ඉටු කරන විට ඇතිවන අවසන් ප්‍රතිඵලය කුමක්ද?", "සාධාරණ, සාමකාමී හා නීතිගරුක සමාජයක් බිහිවීම", "පුද්ගලික වෛරය හා ගැටුම් වැඩි වීම", "මැතිවරණ පැවැත්වීම නතර වීම", "රජයේ බදු පැහැර හැරීම වැඩි වීම", "අයිතීන් හා යුතුකම් නිසි ලෙස ක්‍රියාත්මක වීමෙන් සියලු පුරවැසියන්ට සුරක්ෂිත සමාජයක් උදාවේ."),
    q("ශ්‍රී ලංකාවේ කම්කරු නීතිය යටතේ රැකියා ස්ථානවල සේවකයන්ට වයස අවුරුදු 60/65න් පසු ලැබෙන සමාජ ආරක්ෂණ ප්‍රතිලාභය කුමක්ද?", "විශ්‍රාම වැටුප හෝ EPF/ETF ප්‍රතිලාභ", "පාර්ලිමේන්තු මන්ත්‍රී ආසනයක්", "අධිකරණ විනිසුරු තනතුරක්", "ද්විත්ව ඡන්ද අයිතියක්", "වැඩිහිටි වියේදී ආර්ථික සුරක්ෂිතභාවය සැලසීම සඳහා විශ්‍රාම වැටුප් හා අර්ථසාධක අරමුදල් ක්‍රම පවතී."),
    q("මහජනතාවගේ මූලික අයිතිවාසිකම් උල්ලංඝනය වූ අවස්ථාවක ශ්‍රේෂ්ඨාධිකරණයේ නඩු ගොනු කිරීමේදී මුදල් අපහසුතා ඇති අයට උපකාර වන්නේ කුමක්ද?", "රාජ්‍ය නීති ආධාර සේවය සහ ගාස්තු රහිත මූලික අයිතිවාසිකම් පෙත්සම් පහසුකම", "විදේශීය තානාපති කාර්යාල", "වාණිජ බැංකු ණය", "පළාත් සභා මුදල්", "වධහිංසාවට හෝ අසාධාරණයට ලක්වූ දුප්පත් පුරවැසියන්ට ලිපියකින් පවා ශ්‍රේෂ්ඨාධිකරණයේ පිහිට පැතීමට ඉඩ දී ඇත."),
    q("ශ්‍රී ලංකාවේ ප්‍රථම වරට මානව හිමිකම් පිළිබඳ විධිමත් 'මූලික අයිතිවාසිකම්' පරිච්ඡේදයක් ඇතුළත් කළ ආණ්ඩුක්‍රම ව්‍යවස්ථාව කුමක්ද?", "1972 පළමු ජනරජ ව්‍යවස්ථාව", "1947 සෝල්බරි ව්‍යවස්ථාව", "1931 ඩොනමෝර් ව්‍යවස්ථාව", "1924 මැනිං ව්‍යවස්ථාව", "1972 ව්‍යවස්ථාවේ 18 වන වගන්තියෙන් මූලික අයිතිවාසිකම් හඳුන්වා දුන් අතර 1978 දී අධිකරණ බලාත්මක කිරීම එක් කළේය."),
    q("1972 ව්‍යවස්ථාවේ මූලික අයිතිවාසිකම් සහ 1978 ව්‍යවස්ථාවේ මූලික අයිතිවාසිකම් අතර ප්‍රධාන වෙනස කුමක්ද?", "1978 ව්‍යවස්ථාවෙන් උල්ලංඝනයකදී ශ්‍රේෂ්ඨාධිකරණයට යාමේ පැහැදිලි අධිකරණ ප්‍රතිකාරය හඳුන්වා දීම", "1972 ව්‍යවස්ථාවේ ආගමික නිදහස නොතිබීම", "1978 ව්‍යවස්ථාවෙන් ඡන්ද බලය අහෝසි කිරීම", "1972 ව්‍යවස්ථාවේ අධිකරණ නොතිබීම", "1972 ව්‍යවස්ථාවේ විශේෂ අධිකරණ ක්‍රියාමාර්ගයක් නොතිබූ අතර 1978 (17 හා 126) මඟින් ශ්‍රේෂ්ඨාධිකරණ බලය ලබා දුණි."),
    q("දේශීය හෝ ජාත්‍යන්තර වශයෙන් 'යුද ගැටුම් පවතින කාලයේ පවා' ආරක්ෂා කළ යුතු නිරායුධ සිවිල් වැසියන්ගේ හා තුවාලකරුවන්ගේ අයිතිවාසිකම් අයත් වන්නේ කුමකටද?", "ජාත්‍යන්තර මානුෂීය නීතියට (IHL)", "දේශීය වාණිජ නීතියට", "පළාත් පාලන බදු නීතියට", "සමුපකාර පනතට", "1949 ජිනීවා සම්මුති මඟින් යුද සමයේදී සිවිල් වැසියන් හා රෝගීන් ආරක්ෂා කිරීමේ මානුෂීය නීති නියම කර ඇත."),
    q("පුද්ගලයෙකුට අධිකරණයෙන් නිසි ලෙස වරදකරු කරන තුරු ඔහුගේ ඡායාරූප හා නම 'අපරාධකරුවෙකු' ලෙස මාධ්‍යයේ ප්‍රචාරය නොකළ යුත්තේ ඇයි?", "නිර්දෝෂීභාවයේ පූර්ව නිගමනයට (13(5)) හා මානව ගරුත්වයට ගරු කිරීමට", "පුවත්පත් පිටු ගණන අඩු කිරීමට", "පොලිස් නිලධාරීන් ආරක්ෂා කිරීමට", "මැතිවරණ කාලසටහන රැකීමට", "අධිකරණයෙන් වරද ඔප්පු වන තුරු සෑම සැකකරුවෙකුම නිර්දෝෂී ලෙස සැලකීම ශිෂ්ට නීති මූලධර්මයකි."),
    q("ශ්‍රී ලංකාවේ ළමා අයිතිවාසිකම් සුරැකීම සඳහා 'ළමා ශ්‍රමයෙන් තොර කලාප' ප්‍රකාශයට පත් කිරීමේ අරමුණ කුමක්ද?", "සියලු ළමුන්ට වැඩබිම් වෙනුවට පාසල් අධ්‍යාපනය හා සුරක්ෂිත ළමා වියක් ලබාදීම", "කර්මාන්තශාලා වසා දැමීම", "දිස්ත්‍රික්කවල ජනගහනය අඩු කිරීම", "විශ්‍රාම වයස අඩු කිරීම", "රත්නපුර වැනි දිස්ත්‍රික්කවල නියමු ව්‍යාපෘති ලෙස ළමා ශ්‍රමය තුරන් කිරීමේ වැඩසටහන් ක්‍රියාත්මක විය."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක පුරවැසියන්ට 'රජයේ තොරතුරු දැනගැනීමේ අයිතිය' (RTI) හිමිවීමෙන් ශක්තිමත් වන ප්‍රධාන අගය කුමක්ද?", "රාජ්‍ය පාලනයේ විනිවිදභාවය හා දූෂණ වැළැක්වීම", "පුද්ගලික පවුල් රහස් හෙළි කිරීම", "අධිකරණ නඩු අත්හිටුවීම", "රාජ්‍ය ණය වැඩි කිරීම", "මහජන මුදල් වියදම් වන ආකාරය දැනගැනීමෙන් පුරවැසියන්ට රජය වගවීමට ලක් කළ හැක."),
    q("දේශගුණික විපර්යාස හමුවේ 'අනාගත පරපුර වෙනුවෙන් පරිසරය සුරැකීමේ අයිතිය හා යුතුකම' හඳුන්වන්නේ කුමන සංකල්පයෙන්ද?", "පරම්පරාන්තර සාධාරණත්වය (Intergenerational Equity)", "ඒකපාක්ෂික පාලනය", "බහුවිධ ඡන්ද බලය", "සරල බහුතර ක්‍රමය", "වත්මන් පරපුර සම්පත් පරිභෝජනයේදී අනාගත දරුවන්ගේ ජීවත්වීමේ අයිතියට හානි නොකළ යුතුය."),
    q("නූතන ලෝකයේ 'පුරවැසි යුතුකම්' පිළිබඳව සැලකීමේදී දුර්වල හා ආබාධිත ප්‍රජාව කෙරෙහි අප සතු මූලික වගකීම කුමක්ද?", "අනුකම්පාවෙන් කොන් නොකර සමාන අවස්ථා හා ගරුත්වය ලැබෙන පරිසරයක් සැකසීම", "ඔවුන්ව නිවෙස් තුළ පමණක් රඳවා තැබීම", "පොදු ප්‍රවාහනයට ඇතුළු වීම වැළැක්වීම", "අධ්‍යාපන අයිතිය සීමා කිරීම", "ආබාධ සහිත ප්‍රජාවට සමාජයට එක්වීමට ඇති බාධා ඉවත් කිරීම මානුෂීය හා නීතිමය වගකීමකි."),
    q("ශ්‍රී ලංකාවේ 1978 ව්‍යවස්ථාවේ 15(8) වගන්තිය අනුව සන්නද්ධ හමුදා සහ පොලිස් නිලධාරීන්ගේ ඇතැම් මූලික අයිතිවාසිකම් සීමා කළ හැක්කේ ඇයි?", "නිසි රාජකාරි විනය, කාර්යක්ෂමතාව හා ජාතික ආරක්ෂාව පවත්වාගැනීමට", "ඔවුන් පුරවැසියන් නොවන නිසාය", "ඔවුන්ට නඩු පැවරීම වැළැක්වීමට", "මැතිවරණ අත්හිටුවීමට", "ආරක්ෂක අංශවල විනය හා රාජකාරි ස්වභාවය අනුව වැඩවර්ජන හා දේශපාලන ක්‍රියා නීතියෙන් සීමා කර ඇත."),
    q("විශ්ව මානව හිමිකම් ප්‍රකාශනයේ 7 වන වගන්තියෙන් සහ ශ්‍රී ලංකා ව්‍යවස්ථාවේ 12(1) වගන්තියෙන් පොදුවේ තහවුරු කරන මූලධර්මය කුමක්ද?", "නීතිය ඉදිරියේ සියලු දෙනා සමාන බව", "විධායක ජනාධිපතිට සියලු බලතල හිමි බව", "සමානුපාතික මැතිවරණ ක්‍රමය", "පළාත් සභා ක්‍රමය", "රජුගේ සිට සාමාන්‍ය පුරවැසියා දක්වා සැමට එකම නීතිය සමානව ක්‍රියාත්මක වීම නීතියේ ආධිපත්‍යයයි."),
    q("රටේ පාසල් සිසුන් අතර හිංසනය (Bullying) නැවැත්වීම සඳහා සෑම සිසුවෙකුම පුරුදු කළ යුතු ප්‍රධාන ගුණාංගය කුමක්ද?", "සහකම්පනය (Empathy) සහ අනෙකාගේ ගෞරවයට හිංසා නොකිරීම", "කණ්ඩායම් වශයෙන් ගැටුම් ඇති කර ගැනීම", "දුර්වල සිසුන් සමච්චලයට ලක් කිරීම", "ගුරුවරුන්ගේ උපදෙස් නොසලකා හැරීම", "අනෙකාගේ වේදනාව හා අයිතීන් තේරුම් ගෙන ගෞරවයෙන් සැලකීම මානව හිමිකම් සංස්කෘතියේ පදනමයි."),
    q("මානව හිමිකම් පිළිබඳව සලකා බලන විට 'සෑම අයිතිවාසිකමක්ම නීතියෙන් ආරක්ෂා වුවද එය ස්ථාවරව පවතින්නේ කුමන පදනම මතද?'", "පුරවැසියන් එකිනෙකාගේ අයිතිවාසිකම්වලට ගරු කරමින් යුතුකම් ඉටු කිරීම මත", "පොලිස් ස්ථාන ගණන දහ ගුණයකින් වැඩි කිරීම මත", "පාර්ලිමේන්තු මන්ත්‍රී සංඛ්‍යාව වැඩි කිරීම මත", "විදේශීය ණය ලබාගැනීම මත", "නීතිය පමණක් නොව සමාජයේ සදාචාරාත්මක ගරුත්වය හා යුතුකම් ඉටු කිරීම අයිතීන් රැකීමට අත්‍යවශ්‍යය.")
  )
}
